function Jump({ children, onClick, className = "", variant = "hero", icon = true }: { children: React.ReactNode; onClick: () => void; className?: string; variant?: "hero" | "heroOutline" | "darkOutline"; icon?: boolean }) {
  return <Button type="button" variant={variant} onClick={onClick} className={`h-12 px-6 text-[13px] font-bold ${className}`}>{children}{icon && <ArrowUpRight className="ml-2" />}</Button>;
}
const HEADER = 72;
const easeOutExpo = (t: number) => (t === 1 ? 1 : 1 - Math.pow(2, -10 * t));
const SNAP_SECTIONS = ["solucoes", "segmentos", "produtos"];
function docTop(el: Element) { return el.getBoundingClientRect().top + window.scrollY; }
function sectionTarget(id: string) { const el = document.getElementById(id); if (!el) return null; return id === "inicio" ? 0 : Math.max(0, docTop(el) - (id === "anatomia" ? 0 : HEADER)); }
function snapPoints() {
  const pts: number[] = [0];
  for (const id of SNAP_SECTIONS) { const t = sectionTarget(id); if (t != null) pts.push(t); }
  const ana = document.getElementById("anatomia");
  if (ana) { const top = docTop(ana), end = Math.max(top + 6, top + ana.offsetHeight - window.innerHeight), slot = (end - top) / 6; for (let i = 0; i < 6; i++) pts.push(top + slot * (i + 0.275)); }
  return pts.sort((a, b) => a - b);
}
function go(id: string) {
  const lenis = totemState.lenis as (Lenis | null);
  const t = sectionTarget(id);
  if (lenis && t != null) { lenis.scrollTo(t, { duration: 1.2, easing: easeOutExpo }); return; }
  document.getElementById(id)?.scrollIntoView({ behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches ? "instant" : "smooth" });
}
function Eyebrow({ children, light = false }: { children: React.ReactNode; light?: boolean }) { return <span className={`inline-flex items-center gap-3 text-[11px] font-bold uppercase tracking-[0.18em] ${light ? "text-primary" : "text-primary"}`}><span className="h-px w-7 bg-current" />{children}</span>; }
function Reveal({ children, className = "", delay = 0 }: { children: React.ReactNode; className?: string; delay?: number }) { const ref = useRef<HTMLDivElement>(null); const reduce = useReducedMotion(); const { scrollYProgress } = useScroll({ target: ref, offset: ["start end", "start 65%"] }); const p = useSpring(scrollYProgress, { stiffness: 100, damping: 30 }); const opacity = useTransform(p, [delay, 1], [0, 1]); const y = useTransform(p, [delay, 1], [36, 0]); return <motion.div ref={ref} className={`will-change-transform ${className}`} style={reduce ? {} : { opacity, y }}>{children}</motion.div>; }

