function How() {
 const steps = [{name:"Diagnóstico da operação",text:"Entendemos seus fluxos e necessidades."},{name:"Projeto e personalização",text:"Desenhamos a solução ideal para você."},{name:"Fabricação",text:"Produzimos com qualidade e controle próprios."},{name:"Instalação",text:"Colocamos a solução para funcionar."},{name:"Suporte contínuo",text:"Seguimos ao lado da sua operação."}];
 const ref=useRef<HTMLDivElement>(null); const {scrollYProgress}=useScroll({target:ref,offset:["start 80%","end 50%"]});
 return <section id="como-funciona" className="bg-background py-24 md:py-32"><div className="mx-auto max-w-[1320px] px-5 md:px-9"><Reveal><Eyebrow>DO PLANO À PRÁTICA</Eyebrow><h2 className="mt-5 text-3xl font-bold md:text-5xl">Como <span className="text-primary">funciona.</span></h2><p className="mt-4 max-w-[580px] leading-7 text-muted-foreground">Um processo próximo e completo, do primeiro contato ao dia a dia da sua operação.</p></Reveal><div ref={ref} className="relative mt-16 grid gap-10 pl-8 md:grid-cols-5 md:gap-6 md:pl-0"><div className="absolute left-[11px] top-3 bottom-3 w-px bg-border md:left-0 md:right-0 md:top-[17px] md:h-px md:w-full" /><motion.div style={{scaleY:scrollYProgress,transformOrigin:"top"}} className="absolute left-[11px] top-3 bottom-3 w-px bg-primary md:hidden" /><motion.div style={{scaleX:scrollYProgress,transformOrigin:"left"}} className="absolute left-0 right-0 top-[17px] hidden h-px bg-primary md:block" />{steps.map((s,i) => <Reveal key={s.name} delay={i*.08} className="relative"><div className="absolute -left-[29px] top-[3px] grid size-6 place-items-center rounded-full border-2 border-primary bg-background text-[9px] font-bold text-primary md:static md:size-9 md:text-xs">{i+1}</div><h3 className="mt-0 text-base font-bold md:mt-8">{s.name}</h3><p className="mt-2 max-w-[190px] text-sm leading-6 text-muted-foreground">{s.text}</p></Reveal>)}</div></div></section>;
}

function formatPhone(value: string) { const d=value.replace(/\D/g,"").slice(0,11); if(!d)return ""; if(d.length<=2)return `(${d}`; if(d.length<=6)return `(${d.slice(0,2)}) ${d.slice(2)}`; return `(${d.slice(0,2)}) ${d.slice(2,d.length<=10?6:7)}-${d.slice(d.length<=10?6:7)}`; }
function LeadForm({ interest, segmentInterest, onClear }: { interest: string; segmentInterest: string; onClear: () => void }) {
 const [success,setSuccess]=useState(false);
 const {register,handleSubmit,setValue,formState:{errors}}=useForm<Lead>({resolver:zodResolver(leadSchema),defaultValues:{nome:"",empresa:"",cargo:"",whatsapp:"",email:"",segmento:"",unidades:"",totens:"",objetivo:"",prazo:"",mensagem:""}});
 useEffect(() => { if(interest) {setValue("objetivo","projeto especial");setValue("mensagem",`Tenho interesse na ficha técnica da ${interest}.`);} },[interest,setValue]);
  useEffect(() => { if (segmentInterest) setValue("segmento",segmentInterest.toLowerCase(),{shouldValidate:true}); }, [segmentInterest,setValue]);
 const field="h-12 w-full rounded-md border border-border bg-background px-4 text-sm text-foreground outline-none transition-colors placeholder:text-muted-foreground focus:border-primary focus:ring-2 focus:ring-primary/10";
 const label="mb-2 block text-xs font-bold text-foreground";
 const input=(name:keyof Lead,title:string,placeholder:string,type="text")=><div><label htmlFor={name} className={label}>{title}</label><input id={name} type={type} placeholder={placeholder} {...register(name)} className={field} aria-invalid={!!errors[name]} />{errors[name]&&<p className="mt-1 text-xs text-destructive">{errors[name]?.message}</p>}</div>;
 const select=(name:keyof Lead,title:string,options:string[])=><div><label htmlFor={name} className={label}>{title}</label><select id={name} {...register(name)} className={field} aria-invalid={!!errors[name]}><option value="">Selecione uma opção</option>{options.map(o=><option value={o.toLowerCase()} key={o}>{o}</option>)}</select>{errors[name]&&<p className="mt-1 text-xs text-destructive">{errors[name]?.message}</p>}</div>;
 return <section id="contato" className="relative overflow-hidden bg-gradient-to-br from-primary to-primary-deep py-24 text-primary-foreground md:py-32"><div className="top-glow pointer-events-none absolute inset-0" /><div className="relative mx-auto grid max-w-[1320px] gap-14 px-5 md:px-9 lg:grid-cols-[.8fr_1.2fr] lg:gap-20"><Reveal><span className="[&>span]:text-primary-foreground"><Eyebrow light>VAMOS CONVERSAR</Eyebrow></span><h2 className="mt-6 text-3xl font-bold leading-tight md:text-5xl">Vamos desenhar o <span className="text-primary-soft">autoatendimento</span> da sua operação.</h2><p className="mt-6 max-w-[420px] text-base leading-8 text-primary-foreground/90">Conte um pouco sobre seu desafio. Um especialista retorna em até 1 dia útil.</p><div className="mt-12 flex items-center gap-4 border-t border-primary-foreground/35 pt-6"><div className="grid size-11 place-items-center border border-primary-foreground/50 text-primary-foreground"><Clock3 size={20} /></div><p className="text-sm text-primary-foreground/90">Seu próximo passo começa aqui.</p></div></Reveal><Reveal delay={.1}><div className="border border-border bg-background p-6 text-foreground shadow-lg shadow-primary-deep/15 md:p-9">{success ? <motion.div initial={{opacity:0,scale:.96}} animate={{opacity:1,scale:1}} role="status" className="flex min-h-[550px] flex-col items-center justify-center text-center"><div className="grid size-20 place-items-center rounded-full bg-accent text-primary"><Check size={36} /></div><h3 className="mt-7 text-2xl font-bold">Recebemos seu interesse.</h3><p className="mt-3 max-w-[360px] leading-7 text-muted-foreground">Obrigado por contar sobre sua operação. Esta é uma demonstração do formulário; os dados foram registrados apenas no console.</p><Button variant="outline" className="mt-8" onClick={() => {setSuccess(false);onClear();}}>Enviar outra solicitação</Button></motion.div> : <form onSubmit={handleSubmit(data=>{submitLead(data);setSuccess(true);})} noValidate><div className="mb-8 flex items-center justify-between gap-3"><div><span className="text-[10px] font-bold uppercase tracking-[.15em] text-primary">SOLICITAR PROJETO</span><h3 className="mt-2 text-xl font-bold">Fale com um especialista</h3></div><span className="hidden text-xs text-muted-foreground sm:block">* Campos obrigatórios</span></div>{interest&&<div className="mb-6 flex items-center gap-2 border border-primary/20 bg-accent p-3 text-xs font-medium text-accent-foreground"><Check size={15} className="shrink-0 text-primary" /> Interesse: {interest}</div>}<div className="grid gap-5 sm:grid-cols-2">{input("nome","Nome *","Seu nome")}{input("empresa","Empresa *","Nome da empresa")}{input("cargo","Cargo *","Sua função")}<div><label htmlFor="whatsapp" className={label}>WhatsApp *</label><input id="whatsapp" type="tel" inputMode="tel" placeholder="(00) 00000-0000" {...register("whatsapp",{onChange:e=>setValue("whatsapp",formatPhone(e.target.value))})} className={field} aria-invalid={!!errors.whatsapp} />{errors.whatsapp&&<p className="mt-1 text-xs text-destructive">{errors.whatsapp.message}</p>}</div><div className="sm:col-span-2">{input("email","E-mail corporativo *","voce@empresa.com.br","email")}</div>{select("segmento","Segmento *",segments.map(s=>s.name))}{select("unidades","Número de unidades *",["1","2–5","6–20","20+"])}{select("totens","Quantidade de totens estimada *",["1–2","3–10","10+","Não sei"])}{select("objetivo","Principal objetivo *",["Organizar atendimento/senhas","Self checkout","Pagamentos","Check-in/acesso","Projeto especial"])}<div className="sm:col-span-2">{select("prazo","Prazo *",["Imediato","Até 3 meses","Pesquisando"])}</div><div className="sm:col-span-2"><label htmlFor="mensagem" className={label}>Mensagem <span className="font-normal text-muted-foreground">(opcional)</span></label><textarea id="mensagem" rows={4} placeholder="Conte mais sobre o seu projeto..." {...register("mensagem")} className={`${field} h-auto resize-y py-3`} /></div></div><Button variant="hero" type="submit" className="mt-7 h-13 w-full text-sm font-bold">Solicitar contato do especialista <ArrowRight /></Button><p className="mt-4 text-center text-[11px] leading-5 text-muted-foreground">Seus dados serão usados para retorno sobre sua solicitação.</p></form>}</div></Reveal></div></section>;
}

const faqs=[{q:"Quanto custa um totem?",a:"O investimento varia conforme o modelo, os componentes e as integrações necessárias. Conte sobre seu projeto para receber uma proposta personalizada."},{q:"Integra com meu sistema atual?",a:"Podemos estudar a integração com os sistemas da sua operação. A viabilidade e o escopo são avaliados durante o diagnóstico."},{q:"Qual o prazo de entrega?",a:"O prazo depende do modelo, da personalização e da quantidade de equipamentos. Nossa equipe informa uma estimativa na proposta."},{q:"Tem garantia e manutenção?",a:"Sim. Os totens contam com garantia de fábrica e suporte técnico. As condições são apresentadas na proposta do projeto."},{q:"Vocês atendem todo o Brasil?",a:"Sim. A Vision desenvolve soluções para operações em diferentes regiões do Brasil."}];
