function Home(){const [interest,setInterest]=useState("");const [segmentInterest,setSegmentInterest]=useState("");useEffect(()=>{
  if(window.matchMedia("(prefers-reduced-motion: reduce)").matches)return;
  const lenis=new Lenis({lerp:.12});totemState.lenis=lenis;
  let id=0;const raf=(t:number)=>{lenis.raf(t);id=requestAnimationFrame(raf);};id=requestAnimationFrame(raf);
  // Proximity snap per scene (desktop only)
  let timer=0,snapping=false;
  const cancel=()=>{window.clearTimeout(timer);if(snapping){snapping=false;lenis.stop();lenis.start();}};
  const trySnap=()=>{
    if(window.innerWidth<1024||snapping)return;
    const y=lenis.scroll,H=window.innerHeight;let best=Infinity,target=y;
    for(const p of snapPoints()){const d=Math.abs(p-y);if(d<best){best=d;target=p;}}
    if(best<2||best>H*0.35)return;
    snapping=true;lenis.scrollTo(target,{duration:.9,easing:easeOutExpo,onComplete:()=>{snapping=false;}});
  };
  const onScroll=()=>{if(snapping)return;window.clearTimeout(timer);timer=window.setTimeout(trySnap,120);};
  lenis.on("scroll",onScroll);
  const onClick=(e:MouseEvent)=>{const a=(e.target as HTMLElement).closest?.('a[href^="#"]');if(!a)return;const hash=a.getAttribute("href")!.slice(1);if(!hash||!document.getElementById(hash))return;e.preventDefault();cancel();history.replaceState(null,"","#"+hash);go(hash);};
  const opts={passive:true} as const;
  window.addEventListener("wheel",cancel,opts);window.addEventListener("touchstart",cancel,opts);window.addEventListener("keydown",cancel);window.addEventListener("pointerdown",cancel,opts);document.addEventListener("click",onClick);
  return()=>{cancelAnimationFrame(id);window.clearTimeout(timer);window.removeEventListener("wheel",cancel);window.removeEventListener("touchstart",cancel);window.removeEventListener("keydown",cancel);window.removeEventListener("pointerdown",cancel);document.removeEventListener("click",onClick);totemState.lenis=null;lenis.destroy();};
 },[]);const choose=(name:string)=>{setInterest(name);go("contato");};return <><ErrorBoundary fallback={null}><ClientOnly fallback={null}><Suspense fallback={null}><TotemStage /></Suspense></ClientOnly></ErrorBoundary><Header /><main><Hero /><Solutions /><Anatomy /><Segments setInterestSegment={setSegmentInterest} /><Products choose={choose} /><Clients /><Why /><How /><LeadForm interest={interest} segmentInterest={segmentInterest} onClear={()=>setInterest("")} /><FAQ /></main><Footer /><a href="https://wa.me/5547999670219?text=Ol%C3%A1%21%20Vim%20pelo%20site%20e%20quero%20um%20projeto%20de%20autoatendimento." target="_blank" rel="noreferrer" aria-label="Conversar pelo WhatsApp" title="Conversar pelo WhatsApp" className="fixed bottom-5 right-5 z-40 grid size-14 place-items-center rounded-full bg-whatsapp text-whatsapp-foreground shadow-lg shadow-whatsapp/30 transition-transform hover:scale-105"><MessageCircle size={25} /></a></>}
